# Let's analyze the input/output pairs manually first
inputs = ['ei', 'cxc', 'zkbw', 'xzi', 'cd']
outputs = ['ei', 'xcvi', 'wbekbw', 'xwbei', 'cvid']

print("Inputs:", inputs)
print("Outputs:", outputs)
print()

# Let's look at each transformation individually
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Pair {i}: '{inp}' -> '{outp}'")
    if inp != outp:
        print(f"  Changed at positions where characters differ")
        for j, (char_in, char_out) in enumerate(zip(inp, outp)):
            if char_in != char_out:
                print(f"    Position {j}: '{char_in}' -> '{char_out}'")
        if len(outp) > len(inp):
            print(f"    Length increased by {len(outp) - len(inp)}")
        elif len(outp) < len(inp):
            print(f"    Length decreased by {len(inp) - len(outp)}")
    else:
        print(f"  Unchanged")
    print()

